<template>
 <section class="container py-4 management-page members-page">
  <router-link to="/members" class="member-back">← {{ tr('Lista de miembros','Member list') }}</router-link>
  <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p>
  <p v-if="loading" role="status">{{ tr('Cargando…','Loading…') }}</p>
  <template v-else-if="template">
   <header class="management-heading"><div><p class="management-eyebrow">{{ tr('Ficha de miembro','Member record') }}</p><h1>{{ member ? (member.name || tr('Sin nombre','Missing name')+' #'+member.id) : tr('Nuevo miembro','New member') }}</h1><p>{{ member?.email }}<span v-if="member"> · {{ member.phone }}</span></p></div><div v-if="auth.can('members.manage') && member" class="member-toolbar"><button class="btn btn-outline-primary" :disabled="busy" @click="toggleEdit">{{ editing?tr('Cancelar','Cancel'):tr('Editar','Edit') }}</button><button class="btn btn-outline-danger" :disabled="busy" @click="confirmDelete=!confirmDelete">{{ tr('Eliminar','Delete') }}</button></div></header>
   <section v-if="confirmDelete" class="alert alert-warning"><p>{{ tr('¿Eliminar este miembro? Esta acción no se puede deshacer. Los miembros con registros de asistencia o comités no se pueden eliminar.','Delete this member? This cannot be undone. Members with attendance or committee records cannot be deleted.') }}</p><button class="btn btn-danger" :disabled="busy" @click="remove">{{ tr('Confirmar eliminación','Confirm deletion') }}</button> <button class="btn btn-outline-secondary" @click="confirmDelete=false">{{ tr('Cancelar','Cancel') }}</button></section>
   <p v-if="member?.missing_fields?.length" class="alert alert-warning" role="status">{{ tr('Datos faltantes','Missing data') }}: {{ member.missing_fields.map(missingLabel).join(', ') }}. {{ tr('Completa estos datos para quitar la marca.','Complete these fields to clear the flag.') }}</p>
   <form @submit.prevent="save">
    <fieldset :disabled="busy"><section class="management-surface member-panel"><h2>{{ tr('Datos principales','Basic information') }}</h2><p v-if="editing && !member">{{ tr('Completa la ficha con los mismos datos del directorio CSV. Por defecto, el nuevo miembro inicia una familia propia; también puedes elegir una familia existente.','Complete the record using the same fields as the CSV directory. By default, the new member starts their own family; you can also choose an existing family.') }}</p><p v-if="editing">{{ tr('Solo nombre, correo, teléfono y fecha de nacimiento son obligatorios.','Only name, email, phone and date of birth are required.') }}</p>
     <div v-if="editing" class="member-inputs"><label v-for="field in baseFields" :key="field.id">{{ field.label }}{{ field.required?' *':'' }}<input v-model="draft[field.id]" class="form-control" :type="field.type||'text'" :required="field.required && !waived(field.id==='given_name'?'name':field.id)" :maxlength="field.id==='email'?255:field.id==='phone'?50:80" /></label></div>
     <dl v-else class="member-values"><div v-for="field in baseFields" :key="field.id"><dt>{{ field.label }}</dt><dd>{{ member[field.id] || (field.id==='given_name'?member.name:'—') }}</dd></div></dl>
    </section>
    <section v-for="group in groups" :key="group.id" class="management-surface member-panel"><h2>{{ group.label }}</h2><p v-if="group.id==='church'">{{ churchInfo?.name }}<span v-if="churchInfo?.conference_name"> · {{ churchInfo.conference_name }}</span><br />{{ tr('El miembro pertenece a esta iglesia. La organización se asigna automáticamente.','This member belongs to this church. The organization is assigned automatically.') }}</p><div v-if="editing"  class="member-inputs"><label v-for="field in group.fields" :key="field.id">{{ field.label }}{{ field.required?' *':'' }}<div v-if="field.id==='FamilyId'"><select v-model="familyMode" class="form-select"><option v-if="member" value="none">{{ tr('Sin familia asignada','No family assigned') }}</option><option value="existing">{{ tr('Elegir familia existente','Choose existing family') }}</option><option value="new">{{ tr('Crear nueva familia','Create new family') }}</option></select><select v-if="familyMode==='existing'" v-model="familyId" class="form-select" required><option value="">{{ tr('Selecciona una familia','Select a family') }}</option><option v-for="f in families" :key="f.id" :value="f.id">{{ f.names.join(', ') }} · {{ f.id }}</option></select><small v-if="familyMode==='new'">{{ tr('Este miembro iniciará su propia familia. El ID se genera al guardar; luego puedes agregar más miembros a esta familia.','This member will start their own family. An ID is generated when saved; you can add other members to this family later.') }}</small></div><select v-else-if="field.id==='FamilyPosition'" v-model="draft.data.FamilyPosition" class="form-select"><option :value="null">—</option><option v-if="member?.data?.FamilyPosition && !familyPositions.some(p=>p.value===member.data.FamilyPosition)" :value="member.data.FamilyPosition">{{ member.data.FamilyPosition }} ({{ tr('valor anterior','previous value') }})</option><option v-for="position in familyPositions" :key="position.value" :value="position.value">{{ position.label }}</option></select><select v-else-if="field.type==='checkbox'"   v-model="draft.data[field.id]" class="form-select"><option :value="null">—</option><option :value="true">{{ tr('Sí','Yes') }}</option><option :value="false">No</option></select><select v-else-if="field.type==='select'" v-model="draft.data[field.id]" class="form-select"><option :value="null">—</option><option v-for="option in field.options" :key="option">{{ option }}</option></select><textarea v-else-if="field.type==='textarea'" v-model="draft.data[field.id]" class="form-control" maxlength="5000"></textarea><input v-else v-model="draft.data[field.id]" class="form-control" :readonly="['OrgName','OrgCode'].includes(field.id)" :type="inputType(field.type)" :required="field.required && !waived(field.id==='BornOn'?'dob':field.id)" :max="field.type==='dob'?today:undefined" :step="field.type==='number'?'any':undefined" :maxlength="field.type==='phone'?50:500" /></label></div><dl v-else class="member-values"><div v-for="field in group.fields" :key="field.id"><dt>{{ field.label }}</dt><dd>{{ display(member.data?.[field.id]) }}</dd></div></dl></section>
    <div v-if="editing" class="member-toolbar member-save"><button class="btn btn-primary" :disabled="busy">{{ busy?tr('Guardando…','Saving…'):tr('Guardar miembro','Save member') }}</button><button v-if="member" type="button" class="btn btn-outline-secondary" @click="toggleEdit">{{ tr('Cancelar','Cancel') }}</button></div></fieldset>
   </form>
  </template>
 </section>
</template>
<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../stores/authStore'
import {useUiStore} from '../stores/uiStore'
import {membersApi} from '../services/membersApi'
import '../styles/clerk-management.css'
import '../styles/member-directory.css'
const auth=useAuthStore(),ui=useUiStore(),route=useRoute(),router=useRouter(),tr=(es,en)=>ui.locale==='es'?es:en
const churchInfo=ref(null)
const families=ref([]),familyMode=ref('new'),familyId=ref('')
const member=ref(null),template=ref(null),draft=ref({data:{}}),editing=ref(false),loading=ref(true),busy=ref(false),error=ref(''),confirmDelete=ref(false)
const missingLabel=key=>({name:tr('nombre','name'),email:tr('correo','email'),phone:tr('teléfono','phone'),dob:tr('nacimiento','birth date')})[key]||key
const waived=key=>member.value?.missing_fields?.includes(key) && member.value?.missing_data_authorization?.fields?.includes(key)
const today=new Date().toLocaleDateString('en-CA')
const baseFields=computed(()=>[{id:'given_name',label:tr('Nombre','First name'),required:true},{id:'first_surname',label:tr('Primer apellido / LastName','First surname / LastName')},{id:'second_surname',label:tr('Segundo apellido','Second surname')},{id:'email',label:tr('Correo','Email'),type:'email',required:true},{id:'phone',label:tr('Teléfono principal','Primary phone'),type:'tel',required:true}])
const groups=computed(()=>Object.entries({identity:tr('Identidad y nacimiento','Identity and birth'),family:tr('Familia','Family'),contact:tr('Otros teléfonos y privacidad','Other phones and privacy'),address:tr('Dirección','Address'),church:tr('Iglesia y organización','Church and organization'),legacy:tr('Datos anteriores','Previous information')}).map(([id,label])=>({id,label,fields:(template.value?.fields||[]).filter(f=>(f.group||'legacy')===id && !['Latitude','Longitude','NondeliveryDescription','IsConfidential'].includes(f.id) && (id!=='legacy' || (member.value?.data?.[f.id]!=null && f.type!=='dob'))).sort((a,b)=>a.id==='OptionalLine'?1:b.id==='OptionalLine'?-1:0)})).filter(g=>g.fields.length))
const familyPositions=computed(()=>[{value:'Primary',label:tr('Principal','Primary')},{value:'Spouse',label:tr('Cónyuge','Spouse')},{value:'Son',label:tr('Hijo','Son')},{value:'Daughter',label:tr('Hija','Daughter')}])
const inputType=t=>({dob:'date',phone:'tel'})[t]||(['date','email','number'].includes(t)?t:'text')
const display=v=>v===true?tr('Sí','Yes'):v===false?'No':v===null||v===undefined||v===''?'—':String(v)
const message=e=>Object.entries(e.response?.data?.errors||{}).map(([key,values])=>`${key}: ${values.join(' ')}`).join('\n')||e.response?.data?.message||tr('No se pudo completar la operación.','Unable to complete the operation.')
function reset(){familyId.value=member.value?.data?.FamilyId||'';familyMode.value=familyId.value?'existing':member.value?'none':'new';draft.value={template_id:template.value.id,given_name:member.value?.given_name||member.value?.name||'',first_surname:member.value?.first_surname||'',second_surname:member.value?.second_surname||'',email:member.value?.email||'',phone:member.value?.phone||'',data:Object.fromEntries(template.value.fields.map(f=>[f.id,f.id==='OrgName'?churchInfo.value?.name||'':f.id==='OrgCode'?churchInfo.value?.organization_code||'':member.value?.data?.[f.id]??null]))}}
function toggleEdit(){editing.value=!editing.value;confirmDelete.value=false;error.value='';reset()}
watch(()=>route.params.id,async()=>{loading.value=true;error.value='';template.value=null;confirmDelete.value=false;try{if(!route.params.id){if(!auth.can('members.manage')){await router.replace('/members');return}const result=await membersApi.list();template.value=result.template;churchInfo.value=result.church;member.value=null;editing.value=true}else{const result=await membersApi.get(route.params.id);template.value=result.template;churchInfo.value=result.church;member.value=result.member;editing.value=false}families.value=await membersApi.families();reset()}catch(e){error.value=message(e)}finally{loading.value=false}},{immediate:true})
async function save(){busy.value=true;error.value='';try{const result=await membersApi.save(member.value?.id,{...draft.value,family_mode:familyMode.value,family_id:familyId.value||null});if(!member.value)await router.replace(`/members/${result.id}`);else{member.value=result;families.value=await membersApi.families();editing.value=false;reset()}}catch(e){error.value=message(e);window.scrollTo({top:0,behavior:'smooth'})}finally{busy.value=false}}
async function remove(){busy.value=true;error.value='';try{await membersApi.remove(member.value.id);await router.push('/members')}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
